  if (path === 'contact') html = layout(title,path+'/',`<section class="hero inner">${image(0)}<div class="container hero-copy"><p class="eyebrow">CONTACT / DIRECT</p><h1>CONTACT ELLIS SERVICES GROUP.</h1><p>Call or email to begin a direct conversation about Perth roof repairs.</p></div></section><section class="section grid"><div><p class="eyebrow">CALL OR EMAIL</p><h2>Use the contact channel that suits you.</h2><p><a class="button" href="tel:+61405878406">Call 0405878406</a></p><p><a class="button outline" href="mailto:ellisservicesgroup3@outlook.com">Email Ellis Services Group</a></p></div><div class="card"><p class="eyebrow">ADDRESS</p><h2>140 St Georges Terrace, Perth WA 6000</h2><p>For privacy information relating to this website, read the <a href="/privacy/">privacy page</a>.</p></div></section>`);
